import { toNumber as compatToNumber } from 'es-toolkit/compat';
import lodashToNumber from 'lodash/toNumber.js';
const chars='0123456789.+- exX'; // digits, dot, sign, space, e/x
const alpha=chars+'e'; 
let mism=0, n=0; const samples=[];
const same=(a,b)=>Object.is(a,b)||(Number.isNaN(a)&&Number.isNaN(b));
// exhaustive over len 0..3 of the full charset, then random up to 8
const set=[...'0123456789.+- ex'];
function* gen(len){ if(len===0){yield '';return;} for(const p of gen(len-1)) for(const c of set) yield p+c; }
for(let L=0;L<=3;L++) for(const s of gen(L)){ n++; if(!same(compatToNumber(s),lodashToNumber(s))){mism++; if(samples.length<5) samples.push(s);} }
let seed=12345; const rnd=()=>{seed=(seed*1103515245+12345)&0x7fffffff; return seed/0x7fffffff;};
for(let i=0;i<300000;i++){ const L=Math.floor(rnd()*9); let s=''; for(let j=0;j<L;j++) s+=set[Math.floor(rnd()*set.length)]; n++; if(!same(compatToNumber(s),lodashToNumber(s))){mism++; if(samples.length<5) samples.push(s);} }
console.log('tested',n,'mismatches',mism, samples);
" 2>&1

